def drive(me, enemy, arena):
    if not me.can_drive:
        return (0, 0)

    d = distance_to(enemy.x, enemy.y)
    r = hypot(me.x, me.y)

    if r > 5.2 and d > 1.2:
        err = bearing_to(0, 0)
    else:
        err = bearing_to(enemy.x, enemy.y)

    turn = me.turn_rate

    if err > 0:
        if turn > 40:
            return (1, 0.6)
        if err > 35:
            return (0.9, -0.9)
        p = err / 35
        left = 1
        right = 1 - 1.8 * p
    else:
        if turn < -40:
            return (0.6, 1)
        if err < -35:
            return (-0.9, 0.9)
        p = -err / 35
        right = 1
        left = 1 - 1.8 * p

    if left > 1:
        left = 1
    if left < -1:
        left = -1
    if right > 1:
        right = 1
    if right < -1:
        right = -1

    return (left, right)

