def drive(me, enemy, arena):
    # If unable to drive, stay still
    if not me.can_drive:
        return (0.0, 0.0)

    # Bearing to enemy
    bearing = bearing_to(enemy.x, enemy.y)
    # Normalise to [-180,180]
    if bearing > 180:
        bearing -= 360
    elif bearing < -180:
        bearing += 360

    dist = distance_to(enemy.x, enemy.y)

    # If enemy is behind us, turn in place toward them
    if abs(bearing) > 90:
        turn = 1.0 if bearing > 0 else -1.0
        left = -turn
        right = turn
    else:
        # Drive forward, steer proportionally to bearing
        # Reduce speed when very close to avoid overshoot
        speed_factor = 1.0
        if dist < 0.6:
            speed_factor = 0.5
        turn = max(-1.0, min(1.0, bearing / 30.0))
        left = speed_factor * (1.0 - turn * 0.5)
        right = speed_factor * (1.0 + turn * 0.5)

    left = max(-1.0, min(1.0, left))
    right = max(-1.0, min(1.0, right))
    return (left, right)


