def drive(me, enemy, arena):
    # Stay still if we cannot drive
    if not me.can_drive:
        return (0.0, 0.0)

    # Bearing and distance to enemy
    bearing = bearing_to(enemy.x, enemy.y)
    if bearing > 180:
        bearing -= 360
    elif bearing < -180:
        bearing += 360
    dist = distance_to(enemy.x, enemy.y)

    # If enemy is behind, spin in place toward them
    if abs(bearing) > 90:
        turn = 1.0 if bearing > 0 else -1.0
        left = -turn
        right = turn
    else:
        # Drive forward aggressively, slow only when very close
        speed_factor = 1.0
        if dist < 0.5:
            speed_factor = 0.4
        # Proportional steering
        turn = max(-1.0, min(1.0, bearing / 25.0))
        left = speed_factor * (1.0 - turn * 0.5)
        right = speed_factor * (1.0 + turn * 0.5)

    left = max(-1.0, min(1.0, left))
    right = max(-1.0, min(1.0, right))
    return (left, right)


