    # Self‑right if upside down or on a side
    if (me.inverted or me.on_side) and not me.righting:
        cmds.append(self_right())

    # Fire flipper when it is ready and the enemy is in a good position
    flipper = me.weapons.get('front')
    if flipper and flipper.get('ready'):
        dist = distance_to(enemy.x, enemy.y)
        bearing = bearing_to(enemy.x, enemy.y)
        if bearing > 180:
            bearing -= 360
        elif bearing < -180:
            bearing += 360

        # Enemy roughly in front, close, and essentially at rest
        if dist < 1.0 and abs(bearing) < 20 and enemy.speed < 0.5 and not enemy.airborne and not enemy.righting:
            cmds.append(flip('front'))

    return cmds
